CREATE OR REPLACE FUNCTION MKM_TBIU_Member_fn() RETURNS TRIGGER AS $$
Declare
Begin
  If COALESCE(NEW.Points,0)<0 Then
    RAISE EXCEPTION '%', 'Negative Points';
  End If;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

