CREATE OR REPLACE FUNCTION MKM_TBI_Sales_Item_fn() RETURNS TRIGGER AS $$
DECLARE
  dDate   TIMESTAMP   := LOCALTIMESTAMP;
  nCatId  NUMERIC := 0;
  nUserId NUMERIC;
BEGIN
  SELECT Mdate, User_Id
    INTO dDate, nUserId
    FROM MKM_Sale
   WHERE Id = NEW.Sales_Id;
  BEGIN
    SELECT Prod_Id
      INTO NEW.Prod_Id
      FROM MKM_Prod_Serial
     WHERE Serial = NEW.Serial;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      RAISE EXCEPTION '%', 'Unregistered Serial Number';
  END;
  SELECT Cat_Id
    INTO nCatId
    FROM MKM_Product
   WHERE Id = NEW.Prod_Id;
  SELECT SPoints, Wdays
    INTO NEW.Points, NEW.Wdays
    FROM MKM_Cat
   WHERE Id = nCatId;
  NEW.Edate := dDate + NEW.Wdays;
  UPDATE MKM_Member 
     SET Points = COALESCE(Points, 0) + NEW.Points
   WHERE User_Id = nUserId;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

