CREATE OR REPLACE FUNCTION MKM_TBD_Sales_Item_fn() RETURNS TRIGGER AS $$
Declare
  nUserId  NUMERIC;
Begin
  Select User_Id
    Into nUserId
    From MKM_Sale
   Where Id=OLD.Sales_Id;
  UPDATE MKM_Member SET Points=COALESCE(Points,0)-OLD.Points
   WHERE User_Id=nUserId;
Exception
  When Others Then
    NULL;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS MKM_TBD_Sales_Item ON MKM_Sales_Item;
CREATE TRIGGER MKM_TBD_Sales_Item
  BEFORE DELETE
  ON MKM_Sales_Item
  FOR EACH ROW
  EXECUTE FUNCTION MKM_TBD_Sales_Item_fn();

