CREATE OR REPLACE FUNCTION MKM_TBI_Inst_Item_fn() RETURNS TRIGGER AS $$
Declare
  nSaleId  NUMERIC;
  nCatId   NUMERIC := 0;
  nUserId  NUMERIC;
Begin
  Begin
    Select Sales_Id
      Into nSaleId
      From MKM_Sales_Item
      Where Serial=NEW.Serial;
  Exception
    When No_Data_Found Then
      nSaleId := null;
    When Others Then
      nSaleId := null;
  End;
  If nSaleId IS Not NULL Then
    Select User_Id
      Into nUserId
      From MKM_MInstallment
      WHere Id=NEW.Inst_Id;
    Select Prod_Id
      Into NEW.Prod_Id
      From MKM_Prod_Serial
     Where Serial=NEW.Serial;
    Select Cat_Id
      Into nCatId
      FROM MKM_Product
     Where Id=NEW.Prod_Id;
    Select IPoints
      Into NEW.Points
      FROM MKM_Cat
     Where Id=nCatId;
    UPDATE MKM_Member SET Points=COALESCE(Points,0)+NEW.Points
     WHERE User_Id=nUserId;
  Else
    RAISE EXCEPTION '%', 'Unsold Serial Number';
  End If;
Exception
  When Others Then
    NULL;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

